import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const b=JSON.parse('{"title":"符号判决器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/symbol_slicer/index.md","filePath":"v0.2.0-alpha/modules/symbol_slicer/index.md"}'),r={name:"v0.2.0-alpha/modules/symbol_slicer/index.md"};function l(c,t,n,i,h,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="符号判决器" tabindex="-1">符号判决器 <a class="header-anchor" href="#符号判决器" aria-label="Permalink to &quot;符号判决器&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>symbol_slicer</code> · 模块定义版本：4</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>将接收的复数坐标与已定义星座比较，选择距离最近的码元并输出索引。它执行硬判决，适合研究噪声、相位旋转和星座编号对结果的影响。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>符号映射器.out → 符号判决器.in</code> 可做直接对照；另一分支经信道后进入第二个判决器。输入是复数流，输出是码元索引。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（星座输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（码元输出）</td><td><code>symbol_u8</code></td><td>索引；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>判决器的点表顺序、归一化和 D 必须与预期码元定义一致。D 大于 1 时，连续 D 个输入坐标共同形成一个判决对象，输出码元率相应降低。</p><p>收到的坐标可能因噪声或旋转更接近另一个点，从而判错。判决器不会自动完成载波恢复或符号定时恢复；输入分组和相位偏差应在对应环节处理。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>星座模式<br><code>constellation</code></td><td><code>qpsk</code></td><td>BPSK (<code>bpsk</code>)；QPSK (<code>qpsk</code>)；16QAM (<code>qam16</code>)；自定义 (<code>custom</code>)；预设按 I 后 Q 升序编号；BPSK 为 -1、+1，QPSK 除以 √2，16QAM 的 ±1/±3 网格除以 √10。自定义点表按输入顺序从 0 编号，可另选归一化方式。</td><td>可在线应用</td></tr><tr><td>按码元编号排列的点表实部<br><code>points_real</code></td><td><code>[-0.7071067811865475, -0.7071067811865475, 0.7071067811865475, 0.7071067811865475]</code></td><td>按字段类型填写，见下文说明</td><td>可在线应用</td></tr><tr><td>按码元编号排列的点表虚部<br><code>points_imag</code></td><td><code>[-0.7071067811865475, 0.7071067811865475, -0.7071067811865475, 0.7071067811865475]</code></td><td>按字段类型填写，见下文说明</td><td>可在线应用</td></tr><tr><td>点表归一化<br><code>normalization</code></td><td><code>none</code></td><td>保留原坐标 (<code>none</code>)；平均幅度为 1 (<code>amplitude</code>)；平均功率为 1 (<code>power</code>)</td><td>可在线应用</td></tr><tr><td>每个码元的连续复数坐标数 D<br><code>dimensionality</code></td><td><code>1</code></td><td>范围 1 至 1024；本版 D 支持 1–1024；自定义点表按码元顺序连续填写 M×D 个复数坐标，预设为 D=1。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>constellation</code>、<code>points_real</code>、<code>points_imag</code>、<code>normalization</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线调整点表时保持 M 和 D，并按整组提交。比较运行结果时核对已经应用的星座定义，不能只看尚未应用的工程草稿。改变分组结构后重新准备。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="qpsk-映射、判决与理想信道" tabindex="-1">QPSK 映射、判决与理想信道 <a class="header-anchor" href="#qpsk-映射、判决与理想信道" aria-label="Permalink to &quot;QPSK 映射、判决与理想信道&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/qpsk-channel.cnsproj" download>下载 qpsk-channel.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>QPSK 映射、判决与理想信道</p><ul><li>直接判决逐码元一致。理想信道仍保留 GNU 原生 3 点前视，不能将信道两端同索引当作已对齐。</li></ul><p>QPSK 示例的直接判决应恢复源索引。经信道的分支则先检查原生前视造成的位置关系，再讨论噪声导致的判决变化；不能仅把信道两端同下标相减就当作误码率。源和信道均为本机仿真。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>没有加噪也判出不同索引？</strong> 先检查点表顺序、归一化、坐标分组和信道前视，而不是立即增大噪声统计窗口。</p><p><strong>输出只有整数是正常的吗？</strong> 是，硬判决输出码元编号，幅度和距离信息不保留在该索引中。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/09-symbols/">09 码元、星座与判决</a></li></ul>',30)])])}const m=e(r,[["render",l]]);export{b as __pageData,m as default};
